const body = $input.first().json.body || {};
const prompt = String(body.prompt || '').trim();
const width = Number(body.width || 1024);
const height = Number(body.height || 1024);
const dimensionsValid = [width, height].every((value) =>
  Number.isInteger(value) && value >= 512 && value <= 1536 && value % 64 === 0
);

if (!prompt) {
  return [{ json: { valid: false, statusCode: 400, error: "Body must include a non-empty 'prompt' field." } }];
}
if (prompt.length > 2000) {
  return [{ json: { valid: false, statusCode: 400, error: 'Prompt exceeds the 2000-character limit.' } }];
}
if (!dimensionsValid) {
  return [{ json: { valid: false, statusCode: 400, error: 'width and height must be multiples of 64 from 512 through 1536.' } }];
}

const requestedSeed = Number(body.seed);
const seed = Number.isSafeInteger(requestedSeed) && requestedSeed >= 0
  ? requestedSeed
  : Math.floor(Math.random() * 4294967296);
return [{ json: { valid: true, prompt, width, height, seed, enhance: body.enhance === true } }];

const request = $('Validate Image Request').first().json;
const enhanced = $input.first().json?.choices?.[0]?.message?.content;
if (typeof enhanced !== 'string' || !enhanced.trim()) {
  throw new Error('llama-server returned no enhanced prompt');
}
return [{ json: { ...request, effective_prompt: enhanced.trim().slice(0, 1000) } }];

const response = $input.first().json || {};
const promptId = String(response.prompt_id || '').trim();
if (!promptId) {
  return [{ json: { queued: false, statusCode: 502, error: response.error?.message || response.error || 'ComfyUI rejected the prompt.', node_errors: response.node_errors || {} } }];
}
return [{ json: { queued: true, prompt_id: promptId, queue_number: response.number ?? null } }];

const input = $input.first().json;
const promptId = String(input.query?.prompt_id || '').trim();
const valid = /^[a-zA-Z0-9_-]{1,128}$/.test(promptId);
return [{ json: valid
  ? { valid: true, prompt_id: promptId }
  : { valid: false, statusCode: 400, error: "Query must include a valid 'prompt_id'." }
}];

const promptId = $('Validate Status Request').first().json.prompt_id;
const record = $input.first().json?.[promptId] || {};
const images = Object.values(record.outputs || {}).flatMap((output) => output.images || []);
const image = images.find((item) => item && item.filename);
const failed = record.status?.status_str === 'error';
const query = image
  ? ['filename=' + encodeURIComponent(image.filename), 'subfolder=' + encodeURIComponent(image.subfolder || ''), 'type=' + encodeURIComponent(image.type || 'output')].join('&')
  : '';
return [{ json: {
  finished: Boolean(image) || failed,
  success: Boolean(image),
  statusCode: image ? 200 : failed ? 502 : 202,
  prompt_id: promptId,
  image_url: image ? '/view?' + query : null,
  image,
  error: failed ? 'ComfyUI reported a generation error.' : null
} }];
